import sys
import os
import json
import re
from decimal import Decimal

def load_awards_data(packet_dir):
    candidates = [
        os.path.join(packet_dir, "usaspending_awards.json"),
        os.path.join(packet_dir, "usaspending_awards")
    ]
    awards_file = None
    for cand in candidates:
        if os.path.exists(cand):
            awards_file = cand
            break

    if not awards_file:
        for root, _, files in os.walk(packet_dir):
            for f in files:
                if f.lower() == "usaspending_awards.json":
                    awards_file = os.path.join(root, f)
                    break
            if awards_file:
                break

    if not awards_file or not os.path.exists(awards_file):
        return []

    try:
        with open(awards_file, "r", encoding="utf-8") as f:
            data = json.load(f, parse_float=Decimal, parse_int=Decimal)
            if isinstance(data, dict):
                if "results" in data and isinstance(data["results"], list):
                    return data["results"]
                return [data]
            elif isinstance(data, list):
                return data
            return []
    except Exception:
        return []

def clean_date(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str:
        return None
    m = re.match(r"^(\d{4}-\d{2}-\d{2})", val_str)
    if m:
        return m.group(1)
    return val_str

def clean_amount(val):
    if val is None:
        return None
    if isinstance(val, str):
        val = val.strip().replace("$", "").replace(",", "")
        if not val:
            return None
    try:
        d = Decimal(str(val))
        return f"{d:f}"
    except Exception:
        return str(val)

def extract_fact_value(rec, fact_name):
    if fact_name == "performance start":
        pop = rec.get("period_of_performance")
        if isinstance(pop, dict):
            return clean_date(pop.get("start_date")), "date"
        return None, "date"
    elif fact_name == "performance end":
        pop = rec.get("period_of_performance")
        if isinstance(pop, dict):
            return clean_date(pop.get("end_date")), "date"
        return None, "date"
    elif fact_name == "amount obligated":
        val = rec.get("total_obligation")
        return clean_amount(val), "amount"
    elif fact_name == "potential value":
        val = rec.get("base_and_all_options")
        return clean_amount(val), "amount"
    return None, "unknown"

def matches_entity(rec, entity):
    if not isinstance(rec, dict):
        return False
    if str(rec.get("generated_unique_award_id")) == entity:
        return True
    if str(rec.get("id")) == entity:
        return True
    return False

def resolve_fact(records, fact_name):
    doc_name = "usaspending_awards"
    valid_vals = []
    f_type = "unknown"

    for r in records:
        val, f_type = extract_fact_value(r, fact_name)
        if val is not None:
            valid_vals.append(val)

    if not valid_vals:
        return "ABSENT"

    if f_type == "amount":
        try:
            dec_vals = {Decimal(v) for v in valid_vals}
            if len(dec_vals) > 1:
                return "CONFLICT"
            return [valid_vals[0], doc_name]
        except Exception:
            if len(set(valid_vals)) > 1:
                return "CONFLICT"
            return [valid_vals[0], doc_name]
    else:
        if len(set(valid_vals)) > 1:
            return "CONFLICT"
        return [valid_vals[0], doc_name]

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_data = load_awards_data(packet_dir)

    pairs = manifest.get("pairs", [])
    facts_config = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        facts_for_rule = facts_config.get(rule_id, [])
        matching_records = [r for r in awards_data if matches_entity(r, entity)]

        fact_results = {}
        for fact_name in facts_for_rule:
            if not matching_records:
                fact_results[fact_name] = "ABSENT"
            else:
                fact_results[fact_name] = resolve_fact(matching_records, fact_name)

        output[pair] = fact_results

    print(json.dumps(output, indent=1))

if __name__ == "__main__":
    main()
