import sys
import json
import os
import re
from decimal import Decimal
import collections

FIELD_MAP = {
    "performance start": ("period_of_performance.start_date", "date"),
    "performance end": ("period_of_performance.end_date", "date"),
    "amount obligated": ("total_obligation", "amount"),
    "potential value": ("base_and_all_options", "amount"),
}

def get_nested(obj, path):
    parts = path.split(".")
    curr = obj
    for p in parts:
        if isinstance(curr, dict):
            curr = curr.get(p)
        else:
            return None
    return curr

def parse_date(val):
    if val is None:
        return None
    s = str(val).strip()
    if not s:
        return None
    m = re.search(r'\b(\d{4})[-/](\d{2})[-/](\d{2})\b', s)
    if m:
        return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"
    return s

def parse_amount(val):
    if val is None:
        return None
    if isinstance(val, (int, float, Decimal)):
        return (Decimal(str(val)), str(val))
    if isinstance(val, str):
        cleaned = val.replace('$', '').replace(',', '').strip()
        if not cleaned:
            return None
        try:
            return (Decimal(cleaned), cleaned)
        except Exception:
            return (cleaned, cleaned)
    return (str(val), str(val))

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Locate usaspending_awards.json
    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    if not os.path.exists(awards_file):
        for root, _, files in os.walk(packet_dir):
            for file in files:
                if file.lower() == "usaspending_awards.json":
                    awards_file = os.path.join(root, file)
                    break

    awards_data = []
    doc_name = "usaspending_awards"
    if os.path.exists(awards_file):
        doc_name = os.path.splitext(os.path.basename(awards_file))[0]
        with open(awards_file, 'r', encoding='utf-8') as f:
            awards_data = json.load(f)

    # Index awards by identifier
    records_by_id = collections.defaultdict(list)
    for rec in awards_data:
        rec_id = rec.get("generated_unique_award_id")
        if rec_id:
            records_by_id[str(rec_id)].append(rec)
        alt_id = rec.get("id")
        if alt_id is not None:
            if rec not in records_by_id[str(alt_id)]:
                records_by_id[str(alt_id)].append(rec)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        facts = facts_spec.get(rule_id, [])
        matching_records = records_by_id.get(entity, [])

        pair_result = {}
        for fact_name in facts:
            if fact_name not in FIELD_MAP:
                pair_result[fact_name] = "ABSENT"
                continue

            field_path, val_type = FIELD_MAP[fact_name]

            if not matching_records:
                pair_result[fact_name] = "ABSENT"
                continue

            extracted_vals = []
            for rec in matching_records:
                raw_val = get_nested(rec, field_path)
                if val_type == "date":
                    parsed = parse_date(raw_val)
                    if parsed is not None:
                        extracted_vals.append(parsed)
                elif val_type == "amount":
                    parsed = parse_amount(raw_val)
                    if parsed is not None:
                        extracted_vals.append(parsed)

            if not extracted_vals:
                pair_result[fact_name] = "ABSENT"
            else:
                if val_type == "date":
                    first_val = extracted_vals[0]
                    if all(v == first_val for v in extracted_vals):
                        pair_result[fact_name] = [first_val, doc_name]
                    else:
                        pair_result[fact_name] = "CONFLICT"
