import json
import sys
from decimal import Decimal
from pathlib import Path


def extract_performance_start(record):
    pop = record.get("period_of_performance")
    if isinstance(pop, dict):
        val = pop.get("start_date")
        if val is not None and str(val).strip():
            return str(val).strip()[:10]
    return None


def extract_performance_end(record):
    pop = record.get("period_of_performance")
    if isinstance(pop, dict):
        val = pop.get("end_date")
        if val is not None and str(val).strip():
            return str(val).strip()[:10]
    return None


def extract_amount_obligated(record):
    val = record.get("total_obligation")
    if val is not None and str(val).strip() != "":
        try:
            return Decimal(str(val))
        except Exception:
            return None
    return None


def extract_potential_value(record):
    val = record.get("base_and_all_options")
    if val is not None and str(val).strip() != "":
        try:
            return Decimal(str(val))
        except Exception:
            return None
    return None


FACT_RULES = {
    "performance start": (extract_performance_start, "date", "usaspending_awards"),
    "performance end": (extract_performance_end, "date", "usaspending_awards"),
    "amount obligated": (extract_amount_obligated, "amount", "usaspending_awards"),
    "potential value": (extract_potential_value, "amount", "usaspending_awards"),
}


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = Path(sys.argv[1])
    manifest_path = Path(sys.argv[2])

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = packet_dir / "usaspending_awards.json"
    if not awards_file.is_file():
        candidates = list(packet_dir.glob("**/usaspending_awards.json"))
        if candidates:
            awards_file = candidates[0]

    awards_by_id = {}
    if awards_file.is_file():
        with open(awards_file, "r", encoding="utf-8") as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)
        for award in awards_data:
            aid = award.get("generated_unique_award_id")
            if aid:
                awards_by_id.setdefault(aid, []).append(award)

    result = {}
    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        facts_list = facts_by_rule.get(rule_id, [])
        entity_results = {}
        records = awards_by_id.get(entity, [])

        for fact_name in facts_list:
            if fact_name not in FACT_RULES:
                entity_results[fact_name] = "ABSENT"
                continue

            extractor, fact_type, doc_name = FACT_RULES[fact_name]
            extracted_vals = []

            for rec in records:
                val = extractor(rec)
                if val is not None:
                    extracted_vals.append(val)

            if not extracted_vals:
                entity_results[fact_name] = "ABSENT"
            else:
                if fact_type == "date":
                    unique_dates = set(extracted_vals)
                    if len(unique_dates) > 1:
                        entity_results[fact_name] = "CONFLICT"
                    else:
                        entity_results[fact_name] = [extracted_vals[0], doc_name]
                elif fact_type == "amount":
                    first_val = extracted_vals[0]
                    if any(v != first_val for v in extracted_vals):
                        entity_results[fact_name] = "CONFLICT"
                    else:
                        entity_results[fact_name] = [f"{first_val:f}", doc_name]

        result[pair] = entity_results

    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
