import sys
import json
import os
from decimal import Decimal
import collections

FIELD_MAP = {
    ("usa.period_3y", "performance start"): ("usaspending_awards", ["period_of_performance", "start_date"], "date"),
    ("usa.period_3y", "performance end"): ("usaspending_awards", ["period_of_performance", "end_date"], "date"),
    ("usa.obligated_95", "amount obligated"): ("usaspending_awards", ["total_obligation"], "amount"),
    ("usa.obligated_95", "potential value"): ("usaspending_awards", ["base_and_all_options"], "amount"),
}

def get_nested(d, path):
    curr = d
    for key in path:
        if isinstance(curr, dict):
            curr = curr.get(key)
        else:
            return None
    return curr

def format_val(val, val_type):
    if val is None:
        return None
    s = str(val).strip()
    if not s:
        return None
    if val_type == "date":
        # Extract YYYY-MM-DD
        return s.split()[0].split('T')[0]
    elif val_type == "amount":
        return s.replace('$', '').replace(',', '')
    return s

def values_equal(v1, v2, val_type):
    if val_type == "amount":
        try:
            return Decimal(v1) == Decimal(v2)
        except Exception:
            return v1 == v2
    return v1 == v2

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Locate usaspending_awards.json
    awards_file = None
    for fname in os.listdir(packet_dir):
        if fname.lower() == "usaspending_awards.json":
            awards_file = os.path.join(packet_dir, fname)
            break

    records_by_entity = collections.defaultdict(list)
    if awards_file and os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            awards_data = json.load(f, parse_float=Decimal, parse_int=Decimal)

        if isinstance(awards_data, list):
            for rec in awards_data:
                eid = rec.get("generated_unique_award_id")
                if eid:
                    records_by_entity[str(eid)].append(rec)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        facts = facts_spec.get(rule_id, [])

        entity_records = records_by_entity.get(entity, [])
        pair_result = {}

        for fact in facts:
            rule_info = FIELD_MAP.get((rule_id, fact))
            if not rule_info:
                pair_result[fact] = "ABSENT"
                continue

            doc_name, field_path, val_type = rule_info

            values = []
            for rec in entity_records:
                raw_val = get_nested(rec, field_path)
                formatted = format_val(raw_val, val_type)
                if formatted is not None:
                    values.append(formatted)

            if not values:
                pair_result[fact] = "ABSENT"
            else:
                first_val = values[0]
                has_conflict = False
                for other_val in values[1:]:
                    if not values_equal(first_val, other_val, val_type):
                        has_conflict = True
                        break

                if has_conflict:
                    pair_result[fact] = "CONFLICT"
                else:
                    pair_result[fact] = [first_val, doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=1))

if __name__ == "__main__":
    main()
