import sys
import os
import json
import re
from decimal import Decimal


def normalize_date(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str:
        return None
    m = re.match(r"^(\d{4}-\d{2}-\d{2})", val_str)
    if m:
        return m.group(1)
    return val_str


def normalize_amount(val):
    if val is None:
        return None
    val_str = str(val).strip()
    if not val_str:
        return None
    try:
        return Decimal(val_str), val_str
    except Exception:
        return val_str, val_str


def get_fact_value(award, fact_name):
    if fact_name == "performance start":
        pop = award.get("period_of_performance")
        if isinstance(pop, dict):
            raw = pop.get("start_date")
            val = normalize_date(raw)
            return ("date", val)
        return ("date", None)

    elif fact_name == "performance end":
        pop = award.get("period_of_performance")
        if isinstance(pop, dict):
            raw = pop.get("end_date")
            val = normalize_date(raw)
            return ("date", val)
        return ("date", None)

    elif fact_name == "amount obligated":
        raw = award.get("total_obligation")
        parsed = normalize_amount(raw)
        return ("amount", parsed)

    elif fact_name == "potential value":
        raw = award.get("base_and_all_options")
        parsed = normalize_amount(raw)
        return ("amount", parsed)

    return ("unknown", None)


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    awards_file = os.path.join(packet_dir, "usaspending_awards.json")
    awards = []
    if os.path.exists(awards_file):
        with open(awards_file, "r", encoding="utf-8") as f:
            awards = json.load(f, parse_float=str, parse_int=str)

    # Index awards by generated_unique_award_id
    awards_by_id = {}
    for aw in awards:
        award_id = aw.get("generated_unique_award_id")
        if award_id:
            awards_by_id.setdefault(award_id, []).append(aw)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        facts = facts_by_rule.get(rule_id, [])

        entity_awards = awards_by_id.get(entity, [])
        pair_output = {}

        for fact_name in facts:
            if not entity_awards:
                pair_output[fact_name] = "ABSENT"
                continue

            val_type = None
            collected_vals = []

            for aw in entity_awards:
                vtype, val = get_fact_value(aw, fact_name)
                val_type = vtype
                if val is not None:
                    collected_vals.append(val)

            if not collected_vals:
                pair_output[fact_name] = "ABSENT"
            elif val_type == "amount":
                # collected_vals are tuples of (Decimal/key, original_string)
                distinct_keys = {}
                for key, orig_str in collected_vals:
                    distinct_keys.setdefault(key, orig_str)

                if len(distinct_keys) > 1:
                    pair_output[fact_name] = "CONFLICT"
                else:
                    first_key = next(iter(distinct_keys))
                    pair_output[fact_name] = [distinct_keys[first_key], "usaspending_awards"]
            elif val_type == "date":
                distinct_dates = list(dict.fromkeys(collected_vals))
                if len(distinct_dates) > 1:
                    pair_output[fact_name] = "CONFLICT"
                else:
                    pair_output[fact_name] = [distinct_dates[0], "usaspending_awards"]
            else:
                pair_output[fact_name] = "ABSENT"

        output[pair] = pair_output

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()
